from typing import Literal
from pydantic import BaseModel, Field, model_validator

class TriageDecision(BaseModel):
    intent: Literal["refund", "order_status", "escalate"]
    order_id: str | None = Field(
        default=None, pattern=r"^ORD-\d{6}$"
    )
    reason: str = Field(max_length=300)

    @model_validator(mode="after")
    def require_order(self):
        if self.intent == "refund" and self.order_id is None:
            raise ValueError("refund requires an order_id")
        return self

from dataclasses import dataclass
from typing import Callable, Protocol

@dataclass(frozen=True)
class Reply:
    text: str
    status: str
    input_tokens: int
    output_tokens: int
    cost_usd: float

class Adapter(Protocol):
    def generate(self, messages: list[dict]) -> Reply: ...

class ModelClient:
    def __init__(self, adapter: Adapter,
                 account: Callable[[Reply], None]):
        self.adapter = adapter
        self.account = account

    def generate(self, messages: list[dict]) -> Reply:
        reply = self.adapter.generate(messages)
        self.account(reply)
        return reply

def mock_run(goal, decide, checked_execute, verify,
             max_turns=8):
    history = [{"kind": "goal", "text": goal}]
    for turn in range(max_turns):
        decision = decide(history)
        if decision["kind"] == "finish":
            evidence = verify(goal, history)
            return {
                "status": "completed" if evidence else "incomplete",
                "evidence": evidence,
                "history": history,
            }
        result = checked_execute(decision, turn)
        history.append({"kind": "observation", **result})
        if result.get("status") in {"waiting", "unknown"}:
            return {"status": result["status"], "history": history}
    return {"status": "limit", "history": history}

import json

def react(model, messages, tools, execute, verify, turns=8):
    history = list(messages)
    for _ in range(turns):
        reply = model.generate(history, tools)
        history.append(reply.message)
        if not reply.calls:
            return verify(reply.text, history)
        for call in reply.calls:
            result = execute(call)
            history.append({
                "role": "tool", "tool_call_id": call.id,
                "content": json.dumps(result),
            })
            if result.get("status") == "waiting":
                return {"status": "waiting", "history": history}
    return {"status": "limit", "history": history}

from dataclasses import dataclass
from string import Template

@dataclass(frozen=True)
class PromptTemplate:
    name: str
    version: str
    body: str
    required: frozenset[str]

    def render(self, values: dict[str, str]) -> str:
        missing = self.required - values.keys()
        extra = values.keys() - self.required
        if missing or extra:
            raise ValueError(f"invalid variables: {missing}, {extra}")
        return Template(self.body).substitute(values)

def compose(packs, role):
    chosen = [p for p in packs if role in p.roles]
    chosen.sort(key=lambda p: (p.priority, p.name))
    seen = set()
    for pack in chosen:
        if pack.name in seen:
            raise ValueError(f"duplicate pack: {pack.name}")
        seen.add(pack.name)
    manifest = {p.name: p.version for p in chosen}
    body = "\n\n".join(p.text for p in chosen)
    return body, manifest

import html

KINDS = {"document", "tool_result", "email"}

def wrap_data(kind, source, text, limit=6000):
    if kind not in KINDS:
        raise ValueError("unsupported data kind")
    source = html.escape(source, quote=True)
    body = html.escape(text[:limit])
    return (
        f'<{kind} source="{source}" trust="untrusted">\n'
        f'{body}\n</{kind}>'
    )

