def refund_effect_key(tenant, payment, currency, amount_minor):
    identity = {
        "tenant": tenant, "payment": payment,
        "currency": currency, "amount_minor": amount_minor,
    }
    encoded = json.dumps(
        identity, sort_keys=True, separators=(",", ":")
    ).encode()
    return hashlib.sha256(encoded).hexdigest()

ALLOWED = {
    "running": {"waiting", "paused", "completed", "incomplete",
                "denied", "cancelled", "unknown", "limited"},
    "waiting": {"running", "denied", "cancelled", "expired"},
    "paused": {"running", "cancelled"},
}

def change_status(record, target):
    if target not in ALLOWED.get(record.status, set()):
        raise ValueError(f"illegal: {record.status} -> {target}")
    record.status = target

def upgrade_record(raw, current, migrations):
    version = raw.get("schema_version", 1)
    if version > current:
        raise ValueError("state comes from a newer schema")
    while version < current:
        if version not in migrations:
            raise ValueError("unsupported migration path")
        raw = migrations[version](raw)
        next_version = raw["schema_version"]
        if next_version != version + 1:
            raise ValueError("migration did not advance once")
        version = next_version
    return raw

def select_context(items, count, window, output, fixed_tokens):
    remaining = window - output - fixed_tokens
    if remaining < 0:
        raise ValueError("required context exceeds capacity")
    selected = []
    for item in sorted(items, key=lambda x: x["priority"]):
        size = count(item["text"])
        if size > remaining:
            if item.get("required"):
                raise ValueError("required item does not fit")
            continue
        selected.append((item, size))
        remaining -= size
    text = [item["text"] for item, _ in selected]
    manifest = [
        {"id": item["id"], "source": item["source"],
         "tokens": size}
        for item, size in selected
    ]
    return text, manifest

SOURCE_WEIGHT = {"inferred": 0, "user_stated": 1,
                 "system_of_record": 2}

def memory_decision(candidate, current, subject_allowed):
    if not subject_allowed:
        return "reject_subject"
    if candidate["kind"] not in {"preference", "fact", "episode"}:
        return "reject_kind"
    if candidate["contains_secret_or_policy"]:
        return "reject_content"
    if current is None:
        return "insert"
    if candidate["value"] == current["value"]:
        return "deduplicate"
    old = SOURCE_WEIGHT[current["source_type"]]
    new = SOURCE_WEIGHT[candidate["source_type"]]
    if new < old:
        return "retain_and_flag_conflict"
    return "review_or_supersede"

def reciprocal_rank_fusion(lists, constant=60):
    if constant <= 0:
        raise ValueError("constant must be positive")
    scores = {}
    for results in lists:
        seen = set()
        for rank, item_id in enumerate(results, 1):
            if item_id in seen:
                continue
            seen.add(item_id)
            scores[item_id] = scores.get(item_id, 0.0) + (
                1.0 / (constant + rank)
            )
    return sorted(scores, key=lambda key: (-scores[key], key))

def check_citation_ids(claims, evidence):
    problems = []
    for claim in claims:
        ids = claim.get("evidence_ids", [])
        if not ids:
            problems.append("claim has no cited evidence")
        for item_id in ids:
            if item_id not in evidence:
                problems.append(f"unknown evidence: {item_id}")
    return problems

def mean_recall(queries, retrieve, k=10):
    if not queries:
        raise ValueError("empty evaluation set")
    scores = []
    for query in queries:
        relevant = set(query["relevant_ids"])
        if not relevant:
            raise ValueError("score unanswerable queries separately")
        got = set(retrieve(query)[:k])
        scores.append(len(got & relevant) / len(relevant))
    return sum(scores) / len(scores)

def add_evidence(ledger, candidates):
    added = []
    for item in candidates:
        key = (item["source"], item["version"], item["locator"])
        if not item["permitted"] or not item["relevant"]:
            continue
        if key in ledger:
            continue
        ledger[key] = item
        added.append(item["id"])
    return added

