import asyncio
from mcp import Client

async def inspect_demo(server_url):
    async with Client(server_url) as client:
        catalog = await client.list_tools()
        names = {tool.name for tool in catalog.tools}
        if "query_latency" not in names:
            raise ValueError("required demo capability is absent")
        result = await asyncio.wait_for(
            client.call_tool("query_latency", {
                "service": "checkout-api", "window_minutes": 60,
            }), timeout=5.0,
        )
        if result.is_error:
            raise RuntimeError("demo tool reported an error")
        return result.structured_content

async def inspect_task(remote, task_id, validate):
    task = await remote.get_task(task_id)
    if task.state == "completed":
        return {"status": "received",
                "artifacts": validate(task.artifacts)}
    if task.state in {"input-required", "auth-required"}:
        return {"status": "waiting", "request": task}
    if task.state in {"failed", "rejected", "canceled"}:
        return {"status": task.state, "reason": task.reason}
    return {"status": "working", "task_id": task_id}

def investigate_route(state, verdict, limit=3):
    if verdict == "answer":
        return "end"
    if verdict == "propose_action":
        return "approve"
    if verdict == "need_evidence" and state["attempts"] < limit:
        return "investigate"
    state["outcome"] = "escalation_required"
    return "end"

def verification_route(state, verified, limit=3):
    if verified:
        state["outcome"] = "verified_complete"
        return "end"
    if state["attempts"] < limit:
        return "investigate"
    state["outcome"] = "not_recovered"
    return "end"

import hashlib
import json

def proposal_digest(proposal):
    payload = {
        "action": proposal.action,
        "args": proposal.args,
        "resource_version": proposal.resource_version,
    }
    encoded = json.dumps(payload, sort_keys=True,
                         separators=(",", ":"), allow_nan=False)
    return hashlib.sha256(encoded.encode()).hexdigest()

def validate_decision(proposal, decision, policy, now):
    if decision.outcome != "approved":
        return {"status": decision.outcome}
    if decision.proposal_id != proposal.id:
        raise ValueError("wrong proposal")
    if decision.run_id != proposal.run_id:
        raise ValueError("wrong run")
    digest = proposal_digest(proposal)
    if digest != proposal.digest or digest != decision.digest:
        raise ValueError("proposal binding mismatch")
    if now >= proposal.expires_at:
        return {"status": "expired"}
    policy.require_entitled_approvers(proposal, decision)
    return {"status": "authorised",
            "operation_id": proposal.operation_id}

def run_analysis(code, inputs, principal, provider, policy):
    if "main.py" in inputs:
        raise ValueError("reserved input filename")
    policy.require_safe_input_set(inputs, principal)
    sandbox = provider.create(policy)
    try:
        sandbox.write_file("main.py", code.encode())
        for name, content in inputs.items():
            sandbox.write_readonly_input(name, content)
        result = sandbox.execute(
            ["python", "main.py"],
            timeout_s=policy.timeout_s,
            stream_cap_bytes=policy.output_cap_bytes,
        )
        artifacts = sandbox.collect_bounded_outputs(
            "out", max_bytes=policy.artifact_cap_bytes)
        released = policy.scan_and_authorise(
            artifacts, principal)
        return {"exit_reason": result.exit_reason,
                "stdout": result.bounded_stdout,
                "artifacts": released}
    finally:
        provider.destroy_and_record(sandbox.id)

import random

def full_jitter_delay(attempt, base_s=0.5, cap_s=8.0):
    upper = min(cap_s, base_s * (2 ** attempt))
    return random.uniform(0.0, upper)

def retry_allowed(error, operation, budget):
    if not error.is_transient:
        return False
    if operation.has_effect and not operation.safe_to_retry:
        return False
    return budget.try_reserve_retry(operation.dependency)

def resume_compensation(journal, executor):
    while (step := journal.next_pending_compensation()) is not None:
        if step.compensation is None:
            journal.require_manual_recovery(step.id)
            return {"status": "manual_recovery_required"}
        journal.record_compensation_intent(step.id)
        result = executor.perform_or_reconcile(
            step.compensation,
            operation_id=step.compensation_operation_id,
        )
        if result.status == "unknown":
            journal.record_unknown_compensation(step.id)
            return {"status": "compensation_pending"}
        if result.status != "succeeded":
            journal.record_compensation_failure(step.id, result)
            return {"status": "manual_recovery_required"}
        journal.record_compensated(step.id, result)
    return {"status": "compensated"}

class ScriptedModel:
    def __init__(self, decisions):
        self._decisions = iter(decisions)

    def decide(self, context, tools):
        decision = next(self._decisions)
        if callable(decision):
            return decision(context, tools)
        return decision

def assert_rejection_has_no_effect(harness, payments):
    waiting = harness.start("duplicate charge")
    assert waiting.status == "waiting"
    finished = harness.resume(
        waiting.run_id, decision_outcome="rejected")
    assert payments.effects == []
    assert finished.status in {"completed", "escalated"}

def check_protected_effects(events, decisions):
    problems = []
    for event in events:
        if event.kind != "effect_executed":
            continue
        if not event.approval_required:
            continue
        decision = decisions.get(event.proposal_id)
        if decision is None or decision.outcome != "approved":
            problems.append("missing approved decision")
            continue
        if decision.digest != event.proposal_digest:
            problems.append("approval binding mismatch")
        if event.executed_at >= decision.expires_at:
            problems.append("expired approval used")
    return problems

import math

def wilson_interval(successes, n, z=1.96):
    if type(successes) is not int or type(n) is not int:
        raise TypeError("counts must be integers, not booleans")
    if n < 0 or not 0 <= successes <= n:
        raise ValueError("invalid counts")
    if (type(z) not in (int, float)
            or not math.isfinite(z) or z <= 0):
        raise ValueError("z must be finite and positive")
    if n == 0:
        return (0.0, 1.0)
    p = successes / n
    denominator = 1 + z * z / n
    centre = (p + z * z / (2 * n)) / denominator
    half = z * math.sqrt(
        p * (1 - p) / n + z * z / (4 * n * n)
    ) / denominator
    return (centre - half, centre + half)

import random
from statistics import mean

def paired_case_interval(pairs, trials=2000, seed=7):
    if len(pairs) < 2 or trials < 100:
        raise ValueError("insufficient resampling inputs")
    differences = [candidate - baseline
                   for baseline, candidate in pairs]
    rng = random.Random(seed)
    samples = sorted(
        mean(rng.choices(differences, k=len(differences)))
        for _ in range(trials)
    )
    return (samples[int(0.025 * trials)],
            samples[min(trials - 1, int(0.975 * trials))])

def choose_route(request, candidates, policy, budgets):
    eligible = []
    for route in candidates:
        if not policy.allows_data(request, route):
            continue
        if not policy.meets_quality_floor(request, route):
            continue
        if not route.supports(request.required_features):
            continue
        eligible.append(route)
    for route in sorted(eligible, key=lambda item: item.cost_rank):
        reservation = budgets.try_reserve(
            request.tenant_id, request.run_id,
            route.estimated_cost(request))
        if reservation is not None:
            return route, reservation
    raise RuntimeError("no acceptable route within capacity")

def gateway_attempt(request, target, adapter, quota, ledger):
    reservation = quota.reserve(request, target)
    if reservation is None:
        return {"status": "no_capacity"}
    try:
        response = adapter.call(target, request)
    except Exception as error:
        if adapter.confirmed_unprocessed(error):
            quota.release_unconsumed(reservation)
            ledger.record_rejected_attempt(request, target)
            return {"status": "rejected"}
        ledger.record_unknown_usage(request, target, reservation)
        if adapter.is_transient(error):
            return {"status": "uncertain_provider_failure"}
        raise
    else:
        ledger.settle_usage(request, target, response.usage)
        quota.settle_actual(reservation, response.usage)
        return {"status": "completed", "response": response}
    finally:
        quota.release_concurrency(reservation)

APPROVED_SHOP_TOOLS = frozenset({
    "mcp__shop__get_order",
    "mcp__shop__propose_refund",
})

def shop_permission(tool_name, pinned_schema_matches):
    if tool_name not in APPROVED_SHOP_TOOLS:
        return {"allow": False, "reason": "unknown_tool"}
    if not pinned_schema_matches:
        return {"allow": False, "reason": "schema_drift"}
    return {"allow": True, "reason": "approved_contract"}

def merge_evidence(current, update):
    by_id = {item["id"]: item for item in current}
    for item in update:
        previous = by_id.get(item["id"])
        if previous is not None and previous != item:
            raise ValueError("conflicting evidence identity")
        by_id[item["id"]] = item
    return [by_id[key] for key in sorted(by_id)]

def checked_route(proposed, allowed):
    if proposed not in allowed:
        raise ValueError("route outside declared choices")
    return proposed

def route_after_approval(state):
    decision = state["approval"]["decision"]
    if decision == "approve":
        return "execute"
    return "escalate"

def decide_execution(proposal, approval_record, policy):
    risk = policy.risk(proposal)
    if risk >= 5:
        return "escalate", {"reason": "blocked_action"}
    if risk <= 2:
        return "execute", {"decision": "policy_allowed"}
    if risk == 3 and policy.runbook_allows(proposal):
        return "execute", {"decision": "runbook_allowed"}
    validated = policy.validate_approval(
        proposal, approval_record,
        required_approvers=2 if risk == 4 else 1,
    )
    if not validated.ok:
        return "escalate", {"reason": validated.reason}
    return "execute", validated.approval_record

from datetime import timedelta

def validate_metrics_request(request, ctx):
    if request.service_id != ctx.service_id:
        raise PermissionError("service outside incident scope")
    if request.environment != ctx.environment:
        raise PermissionError("environment outside scope")
    if request.metric not in {
        "latency_p95", "error_rate", "rps", "saturation"
    }:
        raise ValueError("unknown metric template")
    duration = request.end - request.start
    if not timedelta(0) < duration <= timedelta(hours=6):
        raise ValueError("window outside permitted range")
    return request

from datetime import timedelta
from math import isfinite

def evaluate_window(start, now, buckets, alerts_ok):
    end = start + timedelta(minutes=10)
    if now < end:
        return "pending"
    expected = [start + timedelta(minutes=i)
                for i in range(10)]
    if [b["start"] for b in buckets] != expected:
        return "insufficient_evidence"
    for bucket in buckets:
        if bucket["requests"] < 100:
            return "insufficient_evidence"
        if not bucket["evidence_ids"]:
            return "insufficient_evidence"
        latency, errors = bucket["p95_ms"], bucket["error_rate"]
        if not (isfinite(latency) and isfinite(errors)
                and latency >= 0 and 0 <= errors <= 1):
            return "insufficient_evidence"
        if bucket["p95_ms"] > 300:
            return "not_recovered"
        if bucket["error_rate"] > 0.005:
            return "not_recovered"
    if not alerts_ok:
        return "not_recovered"
    return "recovered"
